"""Module 06 — Active filters (Floyd 9e Ch.15)."""
import math
from hx import *
def module(lang):
    f = lambda x, d=2: f'{x:,.{d}f}'
    K = [tr(f'Phần {i} · ' + a, f'Part {i} · ' + b) for i, a, b in ((1, 'Nền tảng', 'Foundations'), (2, 'Phương pháp', 'Methods'), (3, 'Ví dụ từ sách', 'Book examples'), (4, 'Sai lầm và mở rộng', 'Pitfalls and extensions'), (5, 'Ứng dụng và tổng kết', 'Applications and summary'))]
    f3 = 1 / (2 * math.pi * 2.2e3 * 0.0015e-6); f19 = 1 / (2 * math.pi * 0.022e-6) * math.sqrt((47e3 + 1.8e3) / (47e3 * 150e3 * 1.8e3)); b19 = 1 / (math.pi * 150e3 * 0.022e-6)
    P = []
    s1 = sl(table([tr('Đáp ứng', 'Response'), tr('Dải thông', 'Passband'), tr('Tần số tới hạn', 'Critical frequencies')], [[tr('Thông thấp', 'Low-pass'), '0 → fc', '1'], [tr('Thông cao', 'High-pass'), 'fc → ∞', '1'], [tr('Thông dải', 'Band-pass'), 'f₁ → f₂', '2'], [tr('Chắn dải', 'Band-stop'), tr('ngoài f₁…f₂', 'outside f₁…f₂'), '2']]),
            K[0], tr('Bốn loại đáp ứng cơ bản', 'The four basic responses'), tr('Tên bộ lọc theo dải tần mà nó cho đi qua.', 'A filter is named after the band of frequencies it passes.'))
    s2 = sl(formula(tr('Cực và tốc độ suy giảm', 'Poles and roll-off'), 'fc = 1/(2πRC)  ,  roll-off = −20 dB/decade × (số cực)'.replace('(số cực)', tr('(số cực)', '(number of poles)'))) + ul([tr('Một cực = một mạch RC', 'One pole = one RC circuit'), tr('−20 dB/decade = −6 dB/octave', '−20 dB/decade = −6 dB/octave')]),
            K[0], tr('Cực và tốc độ suy giảm', 'Poles and the roll-off rate'), tr('Càng nhiều cực thì dốc càng đứng; bậc của bộ lọc bằng số cực.', 'More poles give a steeper skirt; the order of a filter equals its number of poles.'))
    s3 = sl(table([tr('Đặc tính', 'Characteristic'), tr('Dải thông', 'Passband'), tr('Suy giảm', 'Roll-off'), tr('Ưu điểm', 'Strength')], [['Butterworth', tr('phẳng tối đa', 'maximally flat'), tr('vừa phải', 'moderate'), tr('đáp ứng phẳng', 'flat response')], ['Chebyshev', tr('có gợn', 'ripple'), tr('dốc nhất', 'steepest'), tr('chuyển tiếp nhanh', 'fast transition')], ['Bessel', tr('phẳng, pha tuyến tính', 'flat, linear phase'), tr('chậm hơn', 'slower'), tr('giữ dạng xung', 'preserves pulses')]]),
            K[0], tr('Ba đặc tính đáp ứng', 'The three response characteristics'), tr('Hệ số tắt dần DF = 2 − R1/R2 quyết định bộ lọc rơi vào đặc tính nào.', 'The damping factor DF = 2 − R1/R2 decides which characteristic you get.'))
    s4 = sl(fig('assets/figs/m06/fig15_11.png', 'Sallen-Key low-pass filter', tr('Floyd Hình 15–11', 'Floyd Fig. 15–11'), 520) + formula('Sallen-Key LP', 'fc = 1/(2π√(RA·RB·CA·CB))  ,  Butterworth: DF = 1,414 → R1/R2 = 0,586'.replace('1,414', tr('1,414', '1.414')).replace('0,586', tr('0,586', '0.586'))),
            K[0], tr('Bộ lọc thông thấp Sallen-Key hai cực', 'The two-pole Sallen-Key low-pass filter'), tr('Hai khâu RC đặt fc; bộ chia R1/R2 đặt hệ số tắt dần.', 'Two RC sections set fc; the R1/R2 divider sets the damping.'))
    P.append(dict(title=tr('Nền tảng của bộ lọc', 'Filter foundations'), bullets=[tr('Bốn loại đáp ứng', 'Four responses'), tr('Cực và suy giảm', 'Poles and roll-off'), tr('Butterworth, Chebyshev, Bessel', 'Butterworth, Chebyshev, Bessel')], slides=[s1, s2, s3, s4]))
    s5 = sl(fig('assets/figs/m06/fig15_15.png', 'Sallen-Key high-pass filter', tr('Floyd Hình 15–15', 'Floyd Fig. 15–15'), 520) + callout('info', tr('Từ thông thấp sang thông cao', 'From low-pass to high-pass'), tr('Đổi chỗ điện trở và tụ điện giữ nguyên fc và đặc tính.', 'Swapping resistors and capacitors keeps fc and the characteristic.')),
            K[1], tr('Bộ lọc thông cao Sallen-Key', 'The Sallen-Key high-pass filter'), tr('Cùng cấu trúc, tụ nối tiếp nên chặn một chiều và tần số thấp.', 'Same structure, series capacitors block dc and low frequencies.'))
    s6 = sl(ul([tr('Ghép tầng: số cực cộng lại (2 + 2 = 4 cực → −80 dB/decade)', 'Cascading: poles add (2 + 2 = 4 poles → −80 dB/decade)'), tr('Mỗi tầng dùng hệ số tắt dần riêng để tổng hợp thành Butterworth', 'Each stage uses its own damping factor so the total is Butterworth')]) + table(['n', 'DF'], [['2', '1.414'], ['4', '1.848 ; 0.765'], ['6', '1.932 ; 1.414 ; 0.518']]),
            K[1], tr('Ghép tầng và hệ số tắt dần Butterworth', 'Cascading and Butterworth damping factors'), tr('R1/R2 = 2 − DF cho từng tầng (ví dụ 0,068; 0,586; 1,482 cho sáu cực).', 'R1/R2 = 2 − DF for each stage (e.g. 0.068, 0.586, 1.482 for six poles).'))
    s7 = sl(fig('assets/figs/m06/fig15_19.png', 'multiple-feedback band-pass', tr('Floyd Hình 15–19', 'Floyd Fig. 15–19'), 480) + formula(tr('Thông dải hồi tiếp nhiều đường', 'Multiple-feedback band-pass'), 'f0 = (1/2πC)√((R1+R3)/(R1·R2·R3))  ,  BW = 1/(π·R2·C)  ,  Q = f0/BW'),
            K[1], tr('Bộ lọc thông dải hồi tiếp nhiều đường', 'The multiple-feedback band-pass filter'), tr('Một op-amp, hai tụ bằng nhau; R2 quyết định băng thông.', 'One op-amp, two equal capacitors; R2 sets the bandwidth.'))
    s8 = sl(ul([tr('Thông dải bằng ghép thông thấp và thông cao (fc thông thấp > fc thông cao)', 'Band-pass from cascading a low-pass and a high-pass (LP fc > HP fc)'), tr('Chắn dải = cộng ngõ ra thông thấp và thông cao tách rời nhau', 'Band-stop = sum of a low-pass and a high-pass output that are separated'), tr('Biến trạng thái: một mạch cộng và hai mạch tích phân cho ba ngõ ra', 'State-variable: one summer and two integrators give three outputs')]),
            K[1], tr('Thông dải bằng ghép tầng, chắn dải, biến trạng thái', 'Band-pass by cascading, band-stop, state-variable'), tr('Một cấu trúc có thể cho nhiều loại đáp ứng cùng lúc.', 'One structure can supply several responses at once.'))
    P.append(dict(title=tr('Phương pháp thiết kế', 'Design methods'), bullets=[tr('Thông cao Sallen-Key', 'Sallen-Key high-pass'), tr('Ghép tầng Butterworth', 'Butterworth cascades'), tr('Thông dải và chắn dải', 'Band-pass and band-stop')], slides=[s5, s6, s7, s8]))
    s9 = sl(ex(tr('Floyd Bài 3–4', 'Floyd Problems 3–4'), f'fc = 1/(2π × 2,2 kΩ × 0,0015 μF) = {f(f3/1e3,1)} kHz; −20 dB/decade'.replace('2,2', tr('2,2', '2.2')).replace('0,0015', tr('0,0015', '0.0015'))) + ex(tr('Floyd Bài 5–6', 'Floyd Problems 5–6'), tr('BW = 700 Hz, Q ≈ 5,05; f0 = 15 × 1 kHz = 15 kHz', 'BW = 700 Hz, Q ≈ 5.05; f0 = 15 × 1 kHz = 15 kHz')),
            K[2], tr('Đáp ứng cơ bản (Floyd Bài 3–6)', 'Basic responses (Floyd Problems 3–6)'), tr('Lưu ý: không đủ thông tin để suy ra băng thông của bộ lọc thông cao một cực.', 'Note: the bandwidth of a single-pole high-pass cannot be found from R and C alone.'))
    s10 = sl(ex(tr('Floyd Bài 13', 'Floyd Problem 13'), tr('Sáu cực Butterworth: R1/R2 = 0,068 ; 0,586 ; 1,482', 'Six-pole Butterworth: R1/R2 = 0.068, 0.586, 1.482')) + ex(tr('Thiết kế', 'Design'), tr('fc = 1 kHz, C = 0,01 μF → R = 15,9 kΩ; R1 = 0,586·R2', 'fc = 1 kHz, C = 0.01 μF → R = 15.9 kΩ; R1 = 0.586·R2')),
             K[2], tr('Bộ lọc Butterworth (Floyd Bài 13)', 'Butterworth filters (Floyd Problem 13)'), tr('Ba hệ số tắt dần cho ba tầng, mỗi tầng một tỉ số R1/R2.', 'Three damping factors for three stages, one R1/R2 ratio each.'))
    s11 = sl(ex(tr('Floyd Bài 19(b)', 'Floyd Problem 19(b)'), f'R1 = 47 kΩ, R2 = 150 kΩ, R3 = 1,8 kΩ, C = 0,022 μF → f0 = {f(f19,0)} Hz, BW = {f(b19,1)} Hz, Q = {f(f19/b19)}'.replace('1,8', tr('1,8', '1.8')).replace('0,022', tr('0,022', '0.022'))),
             K[2], tr('Thông dải hồi tiếp nhiều đường', 'Multiple-feedback band-pass'), tr('Sách: f0 = 449 Hz, BW = 96,4 Hz (BW chính xác 96,45 Hz).', 'Book: f0 = 449 Hz, BW = 96.4 Hz (exact BW 96.45 Hz).'))
    P.append(dict(title=tr('Ví dụ từ sách', 'Worked examples from the book'), bullets=[tr('Đáp ứng cơ bản', 'Basic responses'), tr('Butterworth', 'Butterworth'), tr('Thông dải', 'Band-pass')], slides=[s9, s10, s11]))
    s12 = sl(callout('warn', tr('Băng thông của bộ lọc thông cao', 'Bandwidth of a high-pass filter'), tr('Không xác định được từ R và C: còn phụ thuộc giới hạn trên của op-amp.', 'It cannot be found from R and C: it also depends on the op-amp’s upper limit.')) + callout('warn', tr('Q và băng thông', 'Q and bandwidth'), tr('Q = f0/BW, không phải BW/f0.', 'Q = f0/BW, not BW/f0.')),
             K[3], tr('Ba bẫy thường gặp', 'Typical traps'), tr('Kiểm tra đơn vị Hz/kHz và dùng f0 = √(f1·f2) cho Q.', 'Check Hz/kHz and use f0 = √(f1·f2) for Q.'))
    s13 = sl(ul([tr('Chebyshev dốc hơn nhưng có gợn; Bessel giữ dạng xung', 'Chebyshev is steeper but rippled; Bessel preserves pulse shape'), tr('Tần số tới hạn theo công thức RC chỉ là xấp xỉ điểm −3 dB khi tắt dần khác Butterworth', 'The RC-formula fc is only an approximation of the −3 dB point when the damping differs from Butterworth')]),
             K[3], tr('Chọn đặc tính', 'Choosing the characteristic'), tr('Chọn theo yêu cầu: phẳng, dốc, hay pha tuyến tính.', 'Pick by requirement: flat, steep or linear phase.'))
    s14 = sl(ul([tr('Dung sai linh kiện làm lệch fc và Q; dùng tụ/điện trở sai số nhỏ', 'Component tolerances shift fc and Q; use tight-tolerance parts'), tr('Op-amp phải có GBW đủ lớn so với fc', 'The op-amp needs a gain–bandwidth product well above fc')]),
             K[3], tr('Giới hạn thực tế', 'Practical limits'), tr('Bộ lọc lý thuyết chỉ đúng khi op-amp đủ nhanh.', 'The ideal filter assumes a fast enough op-amp.'))
    P.append(dict(title=tr('Sai lầm thường gặp', 'Common pitfalls'), bullets=[tr('Q và băng thông', 'Q and bandwidth'), tr('Chọn đặc tính', 'Choosing a characteristic'), tr('Dung sai', 'Tolerances')], slides=[s12, s13, s14]))
    s15 = sl(ul([tr('Minh hoạ: lọc nhiễu tần số cao khỏi tín hiệu cảm biến trước bộ chuyển đổi A/D (chống chồng phổ)', 'Illustrative: filtering high-frequency noise from a sensor signal ahead of the A/D converter (anti-aliasing)'), tr('Minh hoạ: lọc dải hẹp để lấy một tần số tham chiếu, chắn dải để loại nhiễu tần số lưới điện', 'Illustrative: a narrow band-pass to pick out a reference tone and a notch to remove mains hum')]),
             K[4], tr('Lọc tín hiệu cảm biến trên tàu bay', 'Sensor signal filtering on aircraft'), tr('Chỉ minh hoạ nguyên lý, không mô tả hệ thống cụ thể.', 'Illustrations of principle only, not a specific system.'))
    s16 = sl(table([tr('Đại lượng', 'Quantity'), tr('Công thức', 'Formula')], [['fc', '1/(2πRC)'], ['BW (BP)', 'f₂ − f₁'], ['Q, f0', 'f0/BW ; √(f₁f₂)'], ['DF', '2 − R1/R2'], ['MFB', 'BW = 1/(πR2C)']]),
             K[4], tr('Bảng công thức chương 15', 'Chapter 15 formula table'), tr('Năm công thức này giải phần lớn bài tập.', 'These five formulas solve most exercises.'))
    s17 = sl(ul([tr('Cực = bậc; −20 dB/decade mỗi cực', 'Poles = order; −20 dB/decade each'), tr('R1/R2 đặt DF, RC đặt fc', 'R1/R2 sets DF, RC sets fc'), tr('Module sau: dao động và IC 555', 'Next module: oscillators and the 555 timer')]),
             K[4], tr('Ba ý chính', 'Three take-aways'), tr('Nhớ vai trò hai mạng: chọn tần và hồi tiếp.', 'Remember the two networks: frequency-selective and feedback.'))
    P.append(dict(title=tr('Ứng dụng và tổng kết', 'Applications and summary'), bullets=[tr('Lọc cảm biến (minh hoạ)', 'Sensor filtering (illustrative)'), tr('Bảng công thức', 'Formula table'), tr('Ba ý chính', 'Take-aways')], slides=[s15, s16, s17]))
    nt = '<h3>1. ' + tr('Nội dung chi tiết đối chiếu sách', 'Detailed content mapped to the books') + '</h3>' + ul([tr('Floyd §15–1 đáp ứng cơ bản; §15–2 đặc tính Butterworth/Chebyshev/Bessel; §15–3 thông thấp; §15–4 thông cao; §15–5 thông dải (ghép tầng, hồi tiếp nhiều đường, biến trạng thái); §15–6 chắn dải; §15–7 đo đáp ứng.', 'Floyd §15–1 basic responses; §15–2 Butterworth/Chebyshev/Bessel; §15–3 low-pass; §15–4 high-pass; §15–5 band-pass (cascading, multiple feedback, state-variable); §15–6 band-stop; §15–7 measuring responses.'), tr('Đọc thêm: Jaeger 5e Ch.12 §12.3 theo bản đồ đề cương.', 'See also Jaeger 5e Ch.12 §12.3 per the syllabus map.')])
    nt += '<h3>2. ' + tr('Năm ví dụ có lời giải số', 'Five worked examples') + '</h3>' + ''.join([ex('1', f'fc = 1/(2π·2.2k·0.0015μ) = {f(f3/1e3,1)} kHz'), ex('2', 'BW = 3.9 − 3.2 = 0.7 kHz; Q = 3.533/0.7 = 5.05'), ex('3', 'R1/R2 = 2 − DF = 0.068, 0.586, 1.482'), ex('4', f'MFB: f0 = {f(f19,0)} Hz, BW = {f(b19,1)} Hz'), ex('5', 'LP + HP cascade: BW = 5 kHz − 500 Hz = 4.5 kHz')])
    nt += '<h3>3. ' + tr('Bối cảnh lịch sử/lý thuyết', 'History and theory context') + '</h3><p>' + tr('Butterworth (1930) tìm đáp ứng phẳng tối đa; Chebyshev đánh đổi gợn lấy độ dốc; Bessel giữ độ trễ nhóm không đổi. Cấu trúc Sallen–Key (1955) dùng một op-amp cho mỗi tầng hai cực.', 'Butterworth (1930) sought a maximally flat response; Chebyshev trades ripple for steepness; Bessel keeps the group delay constant. The Sallen–Key structure (1955) uses one op-amp per two-pole stage.') + '</p>'
    nt += '<h3>4. ' + tr('Ca ứng dụng trên tàu bay (minh hoạ)', 'Aircraft case study (illustrative)') + '</h3><p>' + tr('Minh hoạ: bộ lọc thông thấp chống chồng phổ trước A/D, bộ lọc notch loại nhiễu nguồn. Không mô tả hệ thống cụ thể.', 'Illustrative: an anti-aliasing low-pass ahead of the A/D converter and a notch against mains hum. Not a specific system.') + '</p>'
    nt += '<h3>5. ' + tr('Bẫy khi làm bài thi', 'Exam pitfalls') + '</h3>' + ul([tr('Nhầm Q = BW/f0.', 'Using Q = BW/f0.'), tr('Quên rằng thông cao không có băng thông xác định từ R và C.', 'Forgetting that a high-pass bandwidth is not determined by R and C.'), tr('Nhầm bậc với số tầng.', 'Confusing order with number of stages.'), tr('Dùng DF thay cho R1/R2 (R1/R2 = 2 − DF).', 'Using DF instead of R1/R2 (R1/R2 = 2 − DF).')])
    return dict(subtitle=tr('Đáp ứng cơ bản, cực, Butterworth/Chebyshev/Bessel, Sallen-Key thông thấp/cao, thông dải và chắn dải (Floyd chương 15).', 'Basic responses, poles, Butterworth/Chebyshev/Bessel, Sallen-Key low/high-pass, band-pass and band-stop (Floyd Chapter 15).'), time=tr('≈ 6 giờ', '≈ 6 h'),
                objectives=[tr('Nhận biết bốn đáp ứng và tính BW, Q', 'Identify the four responses and compute BW, Q'), tr('Tính fc và thiết kế tầng Sallen-Key', 'Compute fc and design Sallen-Key stages'), tr('Chọn DF để đạt Butterworth', 'Choose DF for a Butterworth response'), tr('Tính f0 và BW của bộ lọc hồi tiếp nhiều đường', 'Compute f0 and BW of a multiple-feedback filter')], parts=P, notes=nt)
